import{_ as i,C as s,o as n,c as r,j as o,a as l,E as h,a2 as d}from"./chunks/framework.BiXHgXAn.js";const w=JSON.parse('{"title":"Announcing Built-in Core Utilities for Windows","description":"The journey of enhancing Windows support in Task.","frontmatter":{"title":"Announcing Built-in Core Utilities for Windows","sidebarTitle":"Built-in Core Utilities","description":"The journey of enhancing Windows support in Task.","author":"andreynering","date":"2025-09-15T00:00:00.000Z","tags":["windows","core-utils"],"outline":"deep","editLink":false},"headers":[],"relativePath":"blog/windows-core-utils.md","filePath":"next/blog/windows-core-utils.md"}'),c={name:"blog/windows-core-utils.md"};function u(t,e,p,m,b,f){const a=s("AuthorCard");return n(),r("div",null,[e[0]||(e[0]=o("h1",{id:"announcing-built-in-core-utilities-for-windows",tabindex:"-1"},[l("Announcing Built-in Core Utilities for Windows "),o("a",{class:"header-anchor",href:"#announcing-built-in-core-utilities-for-windows","aria-label":'Permalink to "Announcing Built-in Core Utilities for Windows"'},"​")],-1)),h(a,{author:t.$frontmatter.author},null,8,["author"]),e[1]||(e[1]=d(`<p>When I started Task back in 2017, one of my biggest goals was to build a task runner that would work well on all major platforms, including Windows. At the time, I was using Windows as my main platform, and it caught my attention how much of a pain it was to get a working version of Make on Windows, for example.</p><h2 id="the-very-beginning" tabindex="-1">The very beginning <a class="header-anchor" href="#the-very-beginning" aria-label="Permalink to &quot;The very beginning&quot;">​</a></h2><p>The very first versions, which looked very prototyp-ish, already supported Windows, but it was falling back to Command Prompt (<code>cmd.exe</code>) to run commands if <code>bash</code> wasn&#39;t available in the system. That didn&#39;t mean you couldn&#39;t run Bash commands on Windows necessarily, because if you used Task inside Git Bash, it would expose <code>bash.exe</code> into your <code>$PATH</code>, which made possible for Task to use it. Outside of it, you would be out of luck, though, because running on Command Prompt meant that the commands wouldn&#39;t be really compatible.</p><h2 id="adopting-a-shell-interpreter" tabindex="-1">Adopting a shell interpreter <a class="header-anchor" href="#adopting-a-shell-interpreter" aria-label="Permalink to &quot;Adopting a shell interpreter&quot;">​</a></h2><p>I didn&#39;t take too much time to discover that there was <a href="https://github.com/mvdan/sh" target="_blank" rel="noreferrer">a shell interpreter for Go that was very solid</a>, and I quickly adopted it to ensure we would be able to run commands with consistency across all platforms. It was fun because once adopted, I had the opportunity to <a href="https://github.com/mvdan/sh/pulls?q=is%3Apr+author%3Aandreynering+is%3Aclosed+sort%3Acreated-asc" target="_blank" rel="noreferrer">make some contributions to make it more stable</a>, which I&#39;m sure the author appreciated.</p><h2 id="the-lack-of-core-utilities" tabindex="-1">The lack of core utilities <a class="header-anchor" href="#the-lack-of-core-utilities" aria-label="Permalink to &quot;The lack of core utilities&quot;">​</a></h2><p>There was one important thing missing, though. If you needed to use any core utilities on Windows, like copying files with <code>cp</code>, moving with <code>mv</code>, creating a directory with <code>mkdir -p</code>, that likely would just fail 💥. There were workarounds, of course. You could run <code>task</code> inside Git Bash which exposed core utils in <code>$PATH</code> for you, or you could install these core utils manually (there are a good number of alternative implementations available for download).</p><p>That was still far from ideal, though. One of my biggest goals with Task is that it should &quot;just work&quot;, even on Windows. Requiring additional setup to make things work is exactly what I wanted to avoid.</p><h2 id="they-finally-arrive" tabindex="-1">They finally arrive! <a class="header-anchor" href="#they-finally-arrive" aria-label="Permalink to &quot;They finally arrive!&quot;">​</a></h2><p>And here we are, in 2025, 8 years after the initial release. We might be late, but I&#39;m happy nonetheless. From now on, the following core utilities will be available on Windows. This is the start. We want to add more with time.</p><ul><li><code>base64</code></li><li><code>cat</code></li><li><code>chmod</code></li><li><code>cp</code></li><li><code>find</code></li><li><code>gzip</code></li><li><code>ls</code></li><li><code>mkdir</code></li><li><code>mktemp</code></li><li><code>mv</code></li><li><code>rm</code></li><li><code>shasum</code></li><li><code>tar</code></li><li><code>touch</code></li><li><code>xargs</code></li></ul><h2 id="how-we-made-this-possible" tabindex="-1">How we made this possible <a class="header-anchor" href="#how-we-made-this-possible" aria-label="Permalink to &quot;How we made this possible&quot;">​</a></h2><p>This was made possible via a collaboration with the maintainers of other Go projects.</p><h3 id="u-root-u-root" tabindex="-1">u-root/u-root <a class="header-anchor" href="#u-root-u-root" aria-label="Permalink to &quot;u-root/u-root&quot;">​</a></h3><p>We are using the core utilities implementations in Go from the <a href="https://github.com/u-root/u-root" target="_blank" rel="noreferrer">u-root</a> project. It wasn&#39;t as simple as it sounds because they have originally implemented every core util as a standalone <code>main</code> package, which means we couldn&#39;t just import and use them as libraries. We had some discussion and we agreed on a common <a href="https://github.com/u-root/u-root/blob/main/pkg/core/command.go" target="_blank" rel="noreferrer">interface</a> and <a href="https://github.com/u-root/u-root/blob/main/pkg/core/base.go" target="_blank" rel="noreferrer">base implementation</a>. Then, I refactored one-by-one of the core utils in the list above. This is the reason we don&#39;t have all of them: there are too many! But the good news is that we can refactor more with time and include them in Task.</p><h3 id="mvdan-sh" tabindex="-1">mvdan/sh <a class="header-anchor" href="#mvdan-sh" aria-label="Permalink to &quot;mvdan/sh&quot;">​</a></h3><p>The other collaboration was with the maintainer of the shell interpreter. He agreed on having <a href="https://github.com/mvdan/sh/blob/master/x/coreutils/coreutils.go" target="_blank" rel="noreferrer">an official middleware</a> to expose these core utilities. This means that other projects that use the shell interpreter can also benefit from this work, and as more utilities are included, those projects will benefit as well.</p><h2 id="can-i-choose-whether-to-use-them-or-not" tabindex="-1">Can I choose whether to use them or not? <a class="header-anchor" href="#can-i-choose-whether-to-use-them-or-not" aria-label="Permalink to &quot;Can I choose whether to use them or not?&quot;">​</a></h2><p>Yes. We added a new environment variable called <a href="./../docs/reference/environment#task-core-utils"><code>TASK_CORE_UTILS</code></a> to control if the Go implementations are used or not. By default, this is <code>true</code> on Windows and <code>false</code> on other platforms. You can override it like this:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Enable, even on non-Windows platforms</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">env</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> TASK_CORE_UTILS=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> task</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ...</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Disable, even on Windows</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">env</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> TASK_CORE_UTILS=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> task</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ...</span></span></code></pre></div><p>We&#39;ll consider making this enabled by default on all platforms in the future. In the meantime, we&#39;re still using the system core utils on non-Windows platforms to avoid regressions as the Go implementations may not be 100% compatible with the system ones.</p><h2 id="feedback" tabindex="-1">Feedback <a class="header-anchor" href="#feedback" aria-label="Permalink to &quot;Feedback&quot;">​</a></h2><p>If you have any feedback about this feature, join our <a href="https://discord.com/invite/6TY36E39UK" target="_blank" rel="noreferrer">Discord server</a> or <a href="https://github.com/go-task/task/issues" target="_blank" rel="noreferrer">open an issue</a> on GitHub.</p><p>Also, if Task is useful for you or your company, consider <a href="/donate">sponsoring the project</a>!</p>`,24))])}const g=i(c,[["render",u]]);export{w as __pageData,g as default};
